        const traceEnd = trace.tracePath[traceIndex + 1];
        const isParallel = isVertical5 ? Math.abs(traceStart.x - traceEnd.x) < COINCIDENT_EPS : Math.abs(traceStart.y - traceEnd.y) < COINCIDENT_EPS;
        if (!isParallel) continue;
